import (
    "math"
)

func mean_absolute_deviation(numbers []float64) float64 {
    if len(numbers) == 0 {
        return 0.0
    }

    sum := 0.0
    for _, n := range numbers {
        sum += n
    }
    mean := sum / float64(len(numbers))

    var totalDeviation float64
    for _, n := range numbers {
        totalDeviation += math.Abs(n - mean)
    }

    return totalDeviation / float64(len(numbers))
