    if len(numbers) < 2 {
        return []interface{}{}
    }

    sort.Float64s(numbers)
    minDiff := math.MaxFloat64
    result := []interface{}{}

    for i := 0; i < len(numbers)-1; i++ {
        diff := numbers[i+1] - numbers[i]
        if diff < minDiff {
            minDiff = diff
            result = []interface{}{numbers[i], numbers[i+1]}
        }
    }

    return result
