import (
    "fmt"
)

func is_simple_power(x int, n int) bool {
    if n <= 0 {
        return false
    }
    if x == 1 {
        return n == 1
    }
    if x < 1 {
        return false
    }
    if n == 1 {
        return x == 1
    }
    if x < n {
        return false
    }
    // Handle negative powers: only valid if x is a reciprocal power, but n > 1 and x < 1 not possible here
    // Since x and n are integers, n > 1 and x < n implies x < 1, which we already checked
    // For n > 1, x must be ≥ n^1, and we can iterate k from 1 upward until n^k > x
    k := 1
    for {
        power := n * n // n^k, starting from k=1
        if power == x {
            return true
        }
        if power > x {
            return false
        }
        k++
    }
}
