package sort_array_test

import (
    "sort"
)

func sort_array(arr []int) []int {
    type item struct {
        value int
        ones  int
    }

    var items []item
    for _, v := range arr {
        ones := countOnes(intToBinary(v))
        items = append(items, item{value: v, ones: ones})
    }

    sort.Slice(items, func(i, j int) bool {
        if items[i].ones != items[j].ones {
            return items[i].ones < items[j].ones
        }
        return items[i].value < items[j].value
    })

    result := make([]int, len(items))
    for i, it := range items {
        result[i] = it.value
    }
    return result
}

func countOnes(n int) int {
    count := 0
    for n > 0 {
        count += n & 1
        n >>= 1
    }
    return count
}

func intToBinary(n int) int {
    if n == 0 {
        return 1 // special case: 0 in binary is "0", but we treat it as 0 ones
    }
    binary := ""
    for n > 0 {
        binary = string('0'+rune(binary[0])) + int(n&1)
        n >>= 1
    }
    return binary
}
