func fix_spaces(text string) string {
    var result strings.Builder
    var lastSpace bool
    spaceCount := 0

    for i := 0; i < len(text); i++ {
        char := text[i]
        if char == ' ' {
            if !lastSpace {
                // Start of a space sequence
                spaceCount = 1
                lastSpace = true
            } else {
                spaceCount++
            }
            if spaceCount > 2 {
                // Replace with hyphen
                result.WriteByte('-')
                spaceCount = 0
                lastSpace = false
            } else {
                // Replace with underscore
                result.WriteByte('_')
            }
        } else {
            result.WriteByte(char)
            lastSpace = false
            spaceCount = 0
        }
    }
    return result.String()
}
