func simplify(x string, n string) bool {
    // Split x and n into numerator and denominator
    xParts := strings.Split(x, "/")
    nParts := strings.Split(n, "/")

    numX, _ := strconv.Atoi(xParts[0])
    denomX, _ := strconv.Atoi(xParts[1])
    numN, _ := strconv.Atoi(nParts[0])
    denomN, _ := strconv.Atoi(nParts[1])

    // Compute product: (numX * numN) / (denomX * denomN)
    numerator := numX * numN
    denominator := denomX * denomN

    // Check if numerator is divisible by denominator (i.e., whole number)
    return numerator % denominator == 0
}
