    "math"
)

func do_algebra(operator []string, operand []int) int {
    if len(operator) != len(operand)-1 {
        panic("invalid operator-list length relative to operand")
    }

    result := operand[0]
    for i, op := range operator {
        switch op {
        case "+":
            result += operand[i+1]
        case "-":
            result -= operand[i+1]
        case "*":
            result *= operand[i+1]
        case "//":
            result /= operand[i+1]
        case "**":
            result = int(math.Pow(float64(result), float64(operand[i+1])))
        default:
            panic(fmt.Sprintf("unsupported operator: %s", op))
        }
    }
    return result
}
