package mean_absolute_deviation_test

import (
    "fmt"
    "math"
    "reflect"
    "testing"
)

func mean_absolute_deviation(numbers []float64) float64 {
    if len(numbers) == 0 {
        return 0.0
    }
    mean := 0.0
    for _, n := range numbers {
        mean += n
    }
    mean /= float64(len(numbers))

    var sumAbsDiff float64
    for _, n := range numbers {
        sumAbsDiff += math.Abs(n - mean)
    }
    return sumAbsDiff / float64(len(numbers))
}

func main() {
    // Test 1: Basic case
    got := mean_absolute_deviation([]float64{1.0, 2.0, 3.0, 4.0})
    want := 1.0
    if got != want {
        panic(fmt.Sprintf("Test 1 failed: got %.4f, want %.4f", got, want))
    }

    // Test 2: Single element
    got = mean_absolute_deviation([]float64{5.0})
    want = 0.0
    if got != want {
        panic(fmt.Sprintf("Test 2 failed: got %.4f, want %.4f", got, want))
    }

    // Test 3: All zeros
    got = mean_absolute_deviation([]float64{0.0, 0.0, 0.0})
    want = 0.0
    if got != want {
        panic(fmt.Sprintf("Test 3 failed: got %.4f, want %.4f", got, want))
    }

    // Test 4: Negative numbers
    got = mean_absolute_deviation([]float64{-1.0, -2.0, -3.0})
    want = 1.0
    if got != want {
        panic(fmt.Sprintf("Test 4 failed: got %.4f, want %.4f", got, want))
    }

    // Test 5: Mixed values
    got = mean_absolute_deviation([]float64{10.0, 2.0, 8.0, 4.0})
    // Mean = (10+2+8+4)/4 = 6.0
    // |10-6| + |2-6| + |8-6| + |4-6| = 4 + 4 + 2 + 2 = 12 → MAD = 12 / 4 = 3.0
    want = 3.0
    if got != want {
        panic(fmt.Sprintf("Test 5 failed: got %.4f, want %.4f", got, want))
    }
}
