package change_base

import (
    "fmt"
    "strconv"
)

func change_base(x int, base int) string {
    if base < 2 || base > 9 {
        return ""
    }
    if x == 0 {
        return "0"
    }
    digits := "0123456789"
    result := ""
    for x > 0 {
        result = digits[x%base] + result
        x /= base
    }
    return result
}
