func is_palindrome(text string) bool {
    text = strings.ToLower(strings.ReplaceAll(text, " ", ""))
    return text == reverse(text)
}

func reverse(s string) string {
    runes := []rune(s)
    for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
        runes[i], runes[j] = runes[j], runes[i]
    }
    return string(runes)
}
