func correct_bracketing(brackets string) bool {
    balance := 0
    for _, ch := range brackets {
        if ch == '<' {
            balance++
        } else if ch == '>' {
            balance--
            if balance < 0 {
                return false // more closing than opening
            }
        }
    }
    return balance == 0
