package pluck

import "fmt"

func pluck(arr []int) []int {
    if len(arr) == 0 {
        return []int{}
    }
    minEven := int(^uint(0) >> 1) + 1 // Max int value
    index := -1
    for i, val := range arr {
        if val%2 == 0 && val < minEven {
            minEven = val
            index = i
        }
    }
    if index == -1 {
        return []int{}
    }
    return []int{minEven, index}
}
