func will_it_fly(q []int, w int) bool {
    // Check if the list is a palindrome (balanced)
    n := len(q)
    for i := 0; i < n/2; i++ {
        if q[i] != q[n-1-i] {
            return false
        }
    }
    // Check if sum of elements ≤ w
    sum := 0
    for _, v := range q {
        sum += v
    }
    return sum <= w
