package sort_array_test

import (
	"fmt"
	"reflect"
)

func sort_array(array []int) []int {
	if len(array) == 0 {
		return array
	}
	first := array[0]
	last := array[len(array)-1]
	sum := first + last
	if sum%2 == 1 {
		// Sort in ascending order
		sorted := make([]int, len(array))
		copy(sorted, array)
		for i := 0; i < len(sorted); i++ {
			for j := i + 1; j < len(sorted); j++ {
				if sorted[i] > sorted[j] {
					sorted[i], sorted[j] = sorted[j], sorted[i]
				}
			}
		}
		return sorted
	} else {
		// Sort in descending order
		sorted := make([]int, len(array))
		copy(sorted, array)
		for i := 0; i < len(sorted); i++ {
			for j := i + 1; j < len(sorted); j++ {
				if sorted[i] < sorted[j] {
					sorted[i], sorted[j] = sorted[j], sorted[i]
				}
			}
		}
		return sorted
	}
}

func main() {
	tests := []struct {
		input    []int
		expected []int
}{
	{[]int{}, []int{}},
	{[]int{5}, []int{5}},
	{[]int{2, 4, 3, 0, 1, 5}, []int{0, 1, 2, 3, 4, 5}},
	{[]int{2, 4, 3, 0, 1, 5, 6}, []int{6, 5, 4, 3, 2, 1, 0}},
	{[]int{1, 3, 5, 2, 4}, []int{1, 2, 3, 4, 5}}, // sum = 1+5 = 6 (even) → descending
}

	for _, test := range tests {
		got := sort_array(test.input)
		if !reflect.DeepEqual(got, test.expected) {
			panic(fmt.Sprintf("sort_array(%v) = %v; want %v", test.input, got, test.expected))
		}
	}
}
