package count_up_to_test

import (
    "math"
)

func isPrime(n int) bool {
    if n < 2 {
        return false
    }
    if n == 2 {
        return true
    }
    if n%2 == 0 {
        return false
    }
    max := int(math.Sqrt(float64(n)))
    for i := 3; i <= max; i += 2 {
        if n%i == 0 {
            return false
        }
    }
    return true
}

func count_up_to(n int) []int {
    var primes []int
    for i := 2; i < n; i++ {
        if isPrime(i) {
            primes = append(primes, i)
        }
    }
    return primes
}
