package count_nums

import "fmt"

func count_nums(arr []int) int {
    count := 0
    for _, num := range arr {
        sumDigits := 0
        n := num
        if n < 0 {
            n = -n
            // First signed digit is negative, but we count digits after sign
            // So we process absolute value digits normally
            for n > 0 {
                sumDigits += n % 10
                n /= 10
            }
        } else {
            for n > 0 {
                sumDigits += n % 10
                n /= 10
            }
        }
        if sumDigits > 0 {
            count++
        }
    }
    return count
}
