        }
        return i < j
    })
    return arr
}

func countOnes(n int) int {
    count := 0
    for n != 0 {
        count += n & 1
        n >>= 1
    }
    return count
}

func binaryRepresentation(n int) string {
    if n == 0 {
        return "0"
    }
    var sb string
    for n > 0 {
        sb = fmt.Sprintf("%d", n&1) + sb
        n >>= 1
    }
    return sb
}
