package maximum

import (
    "container/heap"
    "reflect"
    "testing"
)

func maximum(arr []int, k int) []int {
    if k == 0 {
        return []int{}
    }
    if len(arr) == 0 {
        return []int{}
    }

    // Create a max-heap from the array
    h := &IntHeap{values: arr}
    heap.Init(h)

    // Extract k largest elements
    result := make([]int, 0, k)
    for i := 0; i < k; i++ {
        if h.Len() == 0 {
            break
        }
        max := heap.Pop(h).(int)
        result = append(result, max)
        // Re-add the element to heap if not used in final selection (but we pop once)
        // Since we only pop once per extraction, we just collect and continue
        // But heap size decreases, so continue loop
    }
    return result
}

type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] > h[j] } // max-heap
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func TestMaximum(t *testing.T) {
    tests := []struct {
        arr  []int
        k    int
        want []int
    }{
        {[]int{-3, -4, 5}, 3, []int{-4, -3, 5}},
        {[]int{4, -4, 4}, 2, []int{4, 4}},
        {[]int{-3, 2, 1, 2, -1, -2, 1}, 1, []int{2}},
        {[]int{1, 2, 3, 4, 5}, 0, []int{}},
        {[]int{5, 5, 5, 5}, 2, []int{5, 5}},
        {[]int{10, -1, -2, -3}, 2, []int{10, -1}},
        {[]int{1}, 1, []int{1}},
        {[]int{}, 3, []int{}}, // edge: empty array
    }

    for _, test := range tests {
        got := maximum(test.arr, test.k)
        if !reflect.DeepEqual(got, test.want) {
            t.Errorf("maximum(%v, %d) = %v; want %v", test.arr, test.k, got, test.want)
        }
    }
}
