func is_nested(myString string) bool {
    stack := []rune{}
    for _, ch := range myString {
        if ch == '[' {
            stack = append(stack, ch)
        } else if ch == ']' {
            if len(stack) == 0 {
                return false // unmatched closing bracket
            }
            stack = stack[:len(stack)-1]
        }
    }
    // If stack is not empty, there are unmatched opening brackets
    return len(stack) == 0
}

