func simplify(x string, n string) bool {
	// Parse x = a/b and n = c/d
	partsX := strings.Split(x, "/")
	numeratorX, _ := strconv.Atoi(partsX[0])
	denominatorX, _ := strconv.Atoi(partsX[1])

	partsN := strings.Split(n, "/")
	numeratorN, _ := strconv.Atoi(partsN[0])
	denominatorN, _ := strconv.Atoi(partsN[1])

	// Compute numerator of x * n: (a * c) / (b * d)
	numerator := numeratorX * numeratorN
	denominator := denominatorX * denominatorN

	// Simplify the fraction numerator/denominator by GCD
	gcd := func(a, b int) int {
		for b != 0 {
			a, b = b, a%b
		}
		return a
	}

	g := gcd(numerator, denominator)
	simplifiedNum := numerator / g
	simplifiedDen := denominator / g

	// Check if simplified numerator equals 1 → whole number
	return simplifiedNum == 1
}

func main() {
