var planetOrder = []string{
	"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune",
}

func bf(planet1 string, planet2 string) []interface{} {
	if idx1, i1 := indexPlanet(planet1); i1 == -1 || i1 >= len(planetOrder) {
		return []interface{}{}
	}
	if idx2, i2 := indexPlanet(planet2); i2 == -1 || i2 >= len(planetOrder) {
		return []interface{}{}
	}
	if i1 >= i2 {
		return []interface{}{}
	}

	// Return planets between planet1 and planet2, inclusive of lower index, sorted by proximity
	return planetOrder[i1:i2+1]
}

func indexPlanet(name string) (int, int) {
	for i, p := range planetOrder {
		if p == name {
			return i, i
		}
	}
	return -1, -1
}
