	"testing"
)

func do_algebra(operator []string, operand []int) int {
	if len(operator) == 0 || len(operand) < 2 {
		panic("invalid input: operator non-empty, operand at least two elements")
	}
	result := operand[0]
	for i := 0; i < len(operator); i++ {
		op := operator[i]
		nextOperand := operand[i+1]
		switch op {
		case "+":
			result += nextOperand
		case "-":
			result -= nextOperand
		case "*":
			result *= nextOperand
		case "/":
			if nextOperand == 0 {
				panic("division by zero")
			}
			result /= nextOperand
		case "//":
			if nextOperand == 0 {
				panic("floor division by zero")
			}
			result /= nextOperand
		case "**":
			result = int(math.Pow(float64(result), float64(nextOperand)))
		default:
			panic(fmt.Sprintf("unsupported operator: %s", op))
		}
	}
	return result
}
