fn correct_bracketing(brackets: String) -> bool {
    let mut stack = Vec::new();
    for ch in brackets.chars() {
        match ch {
            '<' => stack.push('('),
            '>' => {
                if stack.is_empty() {
                    return false;
                }
                stack.pop();
            }
            _ => unreachable!(), // only '<' and '>' are expected
        }
    }
    stack.is_empty()
