fn count_ones_in_binary(n: isize) -> u32 {
    if n < 0 {
        // For negative numbers, count bits in two's complement representation up to 32 bits
        let mut n = n;
        let mut count = 0;
        for _ in 0..32 {
            if n & 1 == 1 {
                count += 1;
            }
            n >>= 1;
        }
        count
    } else {
        let mut n = n;
        let mut count = 0;
        while n > 0 {
            count += n & 1;
            n >>= 1;
        }
        count
    }
