use std::collections::BinaryHeap;
use std::cmp::Reverse;

/// Given a vector arr of integers and a positive integer k, return a sorted vector 
/// of length k with the maximum k numbers in arr.
/// Example 1:
/// >>> maximum(vec![-3, -4, 5], 3)
/// vec![-4, -3, 5]
/// Example 2:
/// >>> maximum(vec![4, -4, 4], 2)
/// vec![4, 4]
/// Example 3:
/// >>> maximum(vec![-3, 2, 1, 2, -1, -2, 1], 1)
/// vec![2]
/// Note:
/// 1. The length of the vector will be in the range of [1, 1000].
/// 2. The elements in the vector will be in the range of [-1000, 1000].
/// 3. 0 <= k <= len(arr)
fn maximum(arr: Vec<isize>, k: isize) -> Vec<isize> {
    if k == 0 {
        return vec![];
    }
    let mut heap = BinaryHeap::new();
    for &num in &arr {
        heap.push(Reverse(num)); // max-heap using Reverse
        if heap.len() > k {
            heap.pop().unwrap();
        }
    }
    let mut result = Vec::with_capacity(k);
    while let Some(Reverse(num)) = heap.pop() {
        result.push(num);
    }
    result.sort_unstable();
    result
}
