fn triples_sum_to_zero(l: Vec<isize>) -> bool {
    let n = l.len();
    if n < 3 {
        return false;
    }
    let mut nums = l.iter().cloned().collect::<Vec<_>>();
    nums.sort();
    for i in 0..n-2 {
        let left = i;
        let right = n - 1;
        while left < right {
            let sum = nums[left] + nums[right];
            if sum == 0 {
                return true;
            } else if sum < 0 {
                left += 1;
            } else {
                right -= 1;
            }
        }
    }
    false
}

