fn change_base(x: isize, base: isize) -> String {
    if base < 2 || base > 10 {
        panic!("Base must be between 2 and 9 inclusive");
    }
    if x == 0 {
        return "0".to_string();
    }
    let mut num = x;
    let mut result = String::new();
    while num > 0 {
        let remainder = num % base;
        result.push_str(&remainder.to_string());
        num /= base;
    }
    result.chars().rev().collect()
}

#[cfg(test)]
mod tests {
