    fn test_change_base() {
        assert_eq!(change_base(8, 3), "22");
        assert_eq!(change_base(8, 2), "1000");
        assert_eq!(change_base(7, 2), "111");
        assert_eq!(change_base(0, 5), "0");
        assert_eq!(change_base(15, 8), "17"); // 15 in base 8 is 1*8 + 7 → "17"
    }
}
