fn correct_bracketing(brackets: String) -> bool {
    let mut balance = 0;
    for ch in brackets.chars() {
        match ch {
            '<' => balance += 1,
            '>' => balance -= 1,
            _ => return false, // invalid character, though problem assumes valid input
        }
        if balance < 0 {
            return false; // more '>' than '<' at any point
        }
    }
    balance == 0
}

