fn is_happy(s: String) -> bool {
    if s.len() < 3 {
        return false;
    }
    let mut i = 0;
    while i + 2 < s.len() {
        let a = s.chars().nth(i).unwrap();
        let b = s.chars().nth(i + 1).unwrap();
        let c = s.chars().nth(i + 2).unwrap();
        if a == b || b == c || a == c {
            return false;
        }
        i += 3;
    }
    true
}

fn main() {
    assert_eq!(is_happy(String::from("a")), false);        // length < 3
    assert_eq!(is_happy(String::from("aa")), false);      // length < 3
    assert_eq!(is_happy(String::from("abcd")), true);     // 3-letter blocks: abc, bcd — all distinct
    assert_eq!(is_happy(String::from("aabb")), false);    // "aa" and "bb" have repeated chars
    assert_eq!(is_happy(String::from("adb")), true);       // only one block: adb — all distinct
    assert_eq!(is_happy(String::from("xyy")), false);      // "yy" has repeated chars in last 3
}
