fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let limit = (n as f64).sqrt() as isize + 1;
    for i in (3..limit).step_by(2) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn count_up_to(n: isize) -> Vec<isize> {
    (2..n).filter(|&x| is_prime(x)).collect()
}

fn main() {
    assert_eq!(count_up_to(0), Vec::<isize>::new());
    assert_eq!(count_up_to(1), Vec::<isize>::new());
