    assert_eq!(count_up_to(20), vec![2, 3, 5, 7, 11, 13, 17, 19]);
    assert_eq!(count_up_to(1), Vec::<isize>::new());
    assert_eq!(count_up_to(18), vec![2, 3, 5, 7, 11, 13, 17]);
}
