fn make_a_pile(n: isize) -> Vec<isize> {
    let mut pile = Vec::new();
    let mut stones = n;
    for i in 0..n {
        if n % 2 == 1 {
            // n is odd: use next odd number after current stone count
            stones += 2;
        } else {
            // n is even: use next even number after current stone count
            stones += 2;
        }
        pile.push(stones);
    }
    pile
}

