fn is_nested(s: String) -> bool {
    let mut stack = Vec::new();
    for ch in s.chars() {
        match ch {
            '[' => stack.push(ch),
            ']' => {
                if stack.is_empty() {
                    return false; // Unmatched closing bracket
                }
                stack.pop();
            }
            _ {
                // Ignore non-bracket characters
            }
        }
    }
