fn fix_spaces(text: String) -> String {
    let mut result = String::new();
    let mut space_count = 0;

    for c in text.chars() {
        if c == ' ' {
            space_count += 1;
            result.push('-');
        } else {
            space_count = 0;
            result.push(c);
        }
    }

    // Replace sequences of more than 2 spaces with a single -
    let mut final = String::new();
    let mut space_buffer = String::new();

    for c in result.chars() {
        if c == ' ' {
            space_buffer.push(c);
            if space_buffer.len() == 3 {
                final.push('-');
            } else if space_buffer.len() > 2 {
                // Already more than 2, but we only replace full runs of 3+ with one -
                // so we push '-' only once per such run
                final.push('-');
            }
            // Reset buffer after processing
            space_buffer.clear();
        } else {
            space_buffer.clear();
            final.push(c);
        }
    }

    // Handle trailing spaces: if last chars were spaces, replace with single -
    if !space_buffer.is_empty() {
        final.push('-');
    }

    final
}

fn main() {
    assert_eq!(fix_spaces(String::from(" Example")), String::from("Example"));
    assert_eq!(fix_spaces(String::from(" Example 1")), String::from("Example_1"));
    assert_eq!(fix_spaces(String::from(" Example 2")), String::from("_Example-2"));
    assert_eq!(fix_spaces(String::from("_Example 3")), String::from("_Example-3"));
    assert_eq!(fix_spaces(String::from("   Hello    World")), String::from("-Hello-World"));
}
