fn int_to_mini_roman(number: isize) -> String {
    if number < 1 || number > 1000 {
        panic!("Input must be between 1 and 1000");
    }

    const ROMAN: &[(&str, isize)] = &[
        ("m", 1000), ("cd", 900), ("c", 100), ("xc", 90),
        ("l", 50), ("xl", 40), ("x", 10), ("ix", 9),
        ("v", 5), ("iv", 4), ("i", 1),
    ];

    let mut result = String::new();
    let mut num = number;

    for &(roman, value) in ROMAN.iter() {
        while num >= value {
            result.push_str(roman);
            num -= value;
        }
    }

    result
}

