function mean_absolute_deviation(numbers: number[]): number {
  if (numbers.length === 0) {
    return 0;
  }

  const mean = numbers.reduce((sum, val) => sum + val, 0) / numbers.length;
  const absoluteDeviations = numbers.map(val => Math.abs(val - mean));
  const mad = absoluteDeviations.reduce((sum, val) => sum + val, 0) / numbers.length;

  return mad;
}
