function count_nums(arr: number[]): number {
  function sumOfSignedDigits(num: number): number {
    const sign = num < 0 ? -1 : 1;
    const absNum = Math.abs(num);
    const digits: number[] = [];
    let n = absNum;
    while (n > 0) {
      digits.push(n % 10);
      n = Math.floor(n / 10);
    }
    // Reverse to get digits in original order (from most to least significant)
    // But since we process from least to most, we reverse at the end to sum correctly
    // However, since we're summing absolute values of digits regardless of sign, we sum all digits directly
    return digits.reduce((sum, digit) => sum + digit, 0);
  }

  return arr.filter(num => sumOfSignedDigits(num) > 0).length;
}
