function largest_smallest_integers(lst: number[]): [number | undefined, number | undefined] {
  const negatives: number[] = [];
  const positives: number[] = [];

  for (const num of lst) {
    if (num < 0) negatives.push(num);
    else if (num > 0) positives.push(num);
  }

  const largestNegative = negatives.length === 0 ? undefined : Math.max(...negatives);
  const smallestPositive = positives.length === 0 ? undefined : Math.min(...positives);

  return [largestNegative, smallestPositive];
}
