```typescript
function do_algebra(operator: string[], operand: number[]): number {
  if (operator.length === 0 || operand.length < 2) {
    throw new Error("Operator array must have at least one operator and operand array must have at least two elements.");
  }

  let expression = operand[0];
  for (let i = 0; i < operator.length; i++) {
    const op = operator[i];
    const nextOperand = operand[i + 1];
    switch (op) {
      case '+':
        expression += nextOperand;
        break;
      case '-':
        expression -= nextOperand;
        break;
      case '*':
        expression *= nextOperand;
        break;
      case '//':
        expression = Math.floor(expression / nextOperand);
        break;
      case '**':
        expression = Math.pow(expression, nextOperand);
        break;
      default:
        throw new Error(`Unsupported operator: ${op}`);
    }
  }

  return expression;
}
```

