function find_closest_elements(numbers: number[]): [number, number] {
  if (numbers.length < 2) throw new Error('Array must have at least two elements');

  // Sort the array to enable pairwise comparison of adjacent elements
  const sorted = [...numbers].sort((a, b) => a - b);
  let closestPair: [number, number] = [sorted[0], sorted[1]];
  let minDiff = Math.abs(sorted[1] - sorted[0]);

  for (let i = 1; i < sorted.length - 1; i++) {
    const diff = sorted[i + 1] - sorted[i];
    if (diff < minDiff) {
      minDiff = diff;
      closestPair = [sorted[i], sorted[i + 1]];
    }
  }

  return closestPair;
}
```

