function change_base(x: number, base: number): string {
  if (base < 2 || base > 9) {
    throw new Error("Base must be between 2 and 9 inclusive.");
  }
  if (x === 0) return "0";

  const digits = "0123456789";
  let result = "";

  while (x > 0) {
    result = digits[x % base] + result;
    x = Math.floor(x / base);
  }

  return result;
}
```

