function correct_bracketing(brackets: string): boolean {
  let balance = 0;
  for (const char of brackets) {
    if (char === '<') {
      balance++;
    } else if (char === '>') {
      balance--;
      if (balance < 0) return false; // More closing than opening
    }
  }
  return balance === 0;
}

