assert.deepEqual(correct_bracketing("<>"), true, "Balanced: one < and one >");
assert.deepEqual(correct_bracketing("<<><>>"), true, "Nested and sequential: <<><>>");
assert.deepEqual(correct_bracketing("><<>"), false, "First char '>' closes before opening");
assert.deepEqual(correct_bracketing(">><<>>"), false, "Too many closing brackets");
assert.deepEqual(correct_bracketing(""), true, "Empty string is balanced");
assert.deepEqual(correct_bracketing("<<>>"), true, "Multiple balanced pairs");
assert.deepEqual(correct_bracketing(">>>"), false, "Only closing brackets");
```

