```typescript
function pluck(arr: number[]): number[] {
  if (arr.length === 0) return [];

  let smallestEvenValue = Infinity;
  let smallestIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] % 2 === 0) {
      if (arr[i] < smallestEvenValue) {
        smallestEvenValue = arr[i];
        smallestIndex = i;
      }
    }
  }

  if (smallestIndex === -1) {
    return [];
  }

  return [smallestEvenValue, smallestIndex];
}
```

