function will_it_fly(q: number[], w: number): boolean {
  // Check if the array is a palindrome (balanced)
  const isBalanced = q.length === q.length && q.every((val, i) => i === q.length - 1 - i && val === q[q.length - 1 - i]);

  // Compute sum of elements
  const sum = q.reduce((acc, val) => acc + val, 0);

  // Return true only if balanced and sum ≤ w
  return isBalanced && sum <= w;
}
```

