function sort_array(array: number[]): number[] {
  if (array.length === 0) return [];
  const first = array[0];
  const last = array[array.length - 1];
  const sum = first + last;
  return sum % 2 === 0 ? array.slice().sort((a, b) => a - b) : array.slice().sort((a, b) => b - a);
}

