```typescript
function make_a_pile(n: number): number[] {
  const pile: number[] = [];
  let stones = n;

  for (let i = 0; i < n; i++) {
    if (n % 2 === 1) {
      // n is odd: use next odd number starting from n
      pile.push(stones + 2 * i + 1);
    } else {
      // n is even: use next even number starting from n
      pile.push(stones + 2 * i);
    }
  }

  return pile;
}
```

