function reverse_delete(s: string, c: string): [string, boolean] {
  const forbiddenChars = new Set(c);
  const result = s.split('').filter(char => !forbiddenChars.has(char)).join('');
  const isPalindrome = result === result.split('').reverse().join('');
  return [result, isPalindrome];
}
