```typescript
function sort_array(arr: number[]): number[] {
  return arr.sort((a, b) => {
    const countOnes = (x: number) => {
      if (x < 0) return -1; // Handle negatives by treating them as 0 ones (but sort by value)
      return countBitsInBinary(Math.abs(x));
    };

    const onesA = countOnes(a);
    const onesB = countOnes(b);

    if (onesA !== onesB) {
      return onesA - onesB;
    }
    return a - b;
}

function countBitsInBinary(n: number): number {
  let count = 0;
  while (n > 0) {
    count += n & 1;
    n >>= 1;
  }
  return count;
}
```

