function is_nested(string: string): boolean {
  let openCount = 0;
  let hasNested = false;

  for (const char of string) {
    if (char === '[') {
      openCount++;
    } else if (char === ']') {
      if (openCount > 0) {
        // Found a closing bracket with prior open — potential nesting
        hasNested = true;
        openCount--;
      }
    }
  }

  // A valid nested subsequence requires at least one open bracket and one closing
  // that forms a pair — so hasNested must be true and openCount > 0
  return hasNested && openCount > 0;
}

