function int_to_mini_roman(number: number): string {
  if (number < 1 || number > 1000) {
    throw new Error("Input must be between 1 and 1000 inclusive");
  }

  const romanMap = [
    { value: 1000, numeral: 'm' },
    { value: 900, numeral: 'cm' },
    { value: 500, numeral: 'd' },
    { value: 400, numeral: 'cd' },
    { value: 100, numeral: 'c' },
    { value: 90, numeral: 'xc' },
    { value: 50, numeral: 'l' },
    { value: 40, numeral: 'xl' },
    { value: 10, numeral: 'x' },
    { value: 9, numeral: 'ix' },
    { value: 5, numeral: 'v' },
    { value: 4, numeral: 'iv' },
    { value: 1, numeral: 'i' },
  ];

  let result = '';
  for (const { value, numeral } of romanMap) {
    while (number >= value) {
      result += numeral;
      number -= value;
    }
  }

  return result.toLowerCase();
}

