    switch (op) {
      case '+':
        result += nextOperand;
        break;
      case '-':
        result -= nextOperand;
        break;
      case '*':
        result *= nextOperand;
        break;
      case '//':
        result = Math.floor(result / nextOperand);
        break;
      case '**':
        result = Math.pow(result, nextOperand);
        break;
      default:
        throw new Error(`Unsupported operator: ${op}`);
    }
  }
  return result;
}
```

